//! The web app's design tokens (`web/src/styles/tokens.css`, generated by build.rs): colors
//! light and dark, lengths (and those its media queries change), the type scale, the red day's
//! hatching; and the side the sun says, which picks the palette.

use maison_api::sun::Side;

/// A color, straight alpha.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Rgba(pub u8, pub u8, pub u8, pub u8);

impl Rgba {
    /// The same color at `alpha` (0..1) of its own opacity.
    pub fn faded(self, alpha: f32) -> Self {
        Self(
            self.0,
            self.1,
            self.2,
            (f32::from(self.3) * alpha).round() as u8,
        )
    }
}

impl From<Rgba> for sdl3::pixels::Color {
    fn from(c: Rgba) -> Self {
        Self::RGBA(c.0, c.1, c.2, c.3)
    }
}

/// The font a type token draws with.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Face {
    Text,
    Display,
    Brand,
}

/// A type token: weight (each face embedded at the weights the scale draws), size and line
/// height in CSS pixels.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Type {
    pub weight: u16,
    pub size: f32,
    pub line: f32,
    pub face: Face,
}

/// A face at a weight: what a line is drawn with.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Style {
    pub face: Face,
    pub weight: u16,
}

impl Type {
    pub fn style(&self) -> Style {
        Style {
            face: self.face,
            weight: self.weight,
        }
    }

    /// The same token at another weight (a tile's title: the body, at 600).
    pub const fn weight(self, weight: u16) -> Self {
        Self { weight, ..self }
    }
}

#[allow(dead_code)] // the whole token table: the frame draws with some
mod generated {
    use super::{Face, Rgba, Type};
    include!(concat!(env!("OUT_DIR"), "/tokens.rs"));
}

pub use generated::{DARK, LIGHT, Palette, coarse, hatch, px, ty, wide};

/// A length as `@media (min-width: …)` sets it at `width` CSS px: `base` (the `:root` value)
/// unless a breakpoint at or under `width` changes it (`wide::PAGE_MARGIN`).
pub fn at_width(base: f32, breakpoints: &[(f32, f32)], width: f32) -> f32 {
    breakpoints
        .iter()
        .rev()
        .find(|(from, _)| width >= *from)
        .map_or(base, |(_, v)| *v)
}

/// The palette for a side; none known yet, the light one (the web app's first paint).
pub fn palette(side: Option<Side>) -> &'static Palette {
    match side {
        Some(Side::Dark) => &DARK,
        _ => &LIGHT,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tokens_are_the_web_apps() {
        // tokens.css: --raw-cloud #f2f0ea, --raw-night #151a21, --raw-petrol #0e5e68 / #63c0cb
        assert_eq!(LIGHT.ground, Rgba(0xf2, 0xf0, 0xea, 255));
        assert_eq!(DARK.ground, Rgba(0x15, 0x1a, 0x21, 255));
        assert_eq!(LIGHT.accent, Rgba(0x0e, 0x5e, 0x68, 255));
        assert_eq!(DARK.accent, Rgba(0x63, 0xc0, 0xcb, 255));
        // an alias (`var(--status-down)`) and a plain value (#ffffff / transparent)
        assert_eq!(LIGHT.status_down_text, LIGHT.status_down);
        assert_eq!(DARK.tempo_white.3, 0);
        assert_eq!(px::S_4, 16.0);
        assert_eq!(px::TILE_ICON, 48.0);
        assert_eq!(px::DISABLED_OPACITY, 0.55);
        assert_eq!(ty::GROUP.size, 19.0);
        assert_eq!(ty::GROUP.face, Face::Display);
        assert_eq!(ty::BODY.line, 24.0);
        // a unitless line height multiplies the size: `400 1.35rem/1`
        assert_eq!(ty::BRAND.line, ty::BRAND.size);
    }

    #[test]
    fn the_media_queries_and_the_hatch_are_the_web_apps() {
        // `--page-margin: 16px`, 24 from 600, 32 from 1600
        assert_eq!(at_width(px::PAGE_MARGIN, wide::PAGE_MARGIN, 599.0), 16.0);
        assert_eq!(at_width(px::PAGE_MARGIN, wide::PAGE_MARGIN, 600.0), 24.0);
        assert_eq!(at_width(px::PAGE_MARGIN, wide::PAGE_MARGIN, 1600.0), 32.0);
        // a finger: the compact controls grow to the 44 px target
        assert_eq!(coarse::CONTROL_H_S, px::CONTROL_H);
        // 45°, 3 px of red then 3 of red mixed 70 % with the ink
        assert_eq!(
            (hatch::ANGLE, hatch::STRIPE, hatch::PERIOD),
            (45.0, 3.0, 6.0)
        );
        assert_eq!(hatch::MIX, 0.7);
        assert_eq!(hatch::first(&LIGHT), LIGHT.tempo_red);
        assert_eq!(hatch::towards(&DARK), DARK.ink);
    }

    #[test]
    fn the_sun_picks_the_palette() {
        assert_eq!(palette(Some(Side::Dark)), &DARK);
        assert_eq!(palette(Some(Side::Light)), &LIGHT);
        assert_eq!(palette(None), &LIGHT);
    }
}
